using System;using System.IO;using System.IO.Compression;using System.Text;using System.Security.Cryptography;using System.Collections.Generic;
namespace BeamScheduleFormatter {
static class ExcelEstimateData {
 public const string Marker="DTCEEmbeddedEstimateV1";const int Max=100000000;
 public static string[] Pack(string xml){byte[] plain=Encoding.UTF8.GetBytes(xml);if(plain.Length>Max)throw new Exception("Estimate exceeds workbook backup limit.");string hash;using(var sha=SHA256.Create())hash=Convert.ToBase64String(sha.ComputeHash(plain));string payload;using(var stream=new MemoryStream()){using(var zip=new GZipStream(stream,CompressionMode.Compress,true))zip.Write(plain,0,plain.Length);payload=hash+"\n"+Convert.ToBase64String(stream.ToArray());}var chunks=new List<string>();for(int n=0;n<payload.Length;n+=30000)chunks.Add(payload.Substring(n,Math.Min(30000,payload.Length-n)));return chunks.ToArray();}
 public static string Unpack(string[] chunks){if(chunks==null||chunks.Length==0||chunks.Length>5000)throw new Exception("Invalid embedded estimate.");foreach(string c in chunks)if(c==null||c.Length>30000)throw new Exception("Invalid estimate chunk.");string payload=string.Concat(chunks);int split=payload.IndexOf('\n');if(split!=44)throw new Exception("Invalid estimate checksum header.");byte[] packed=Convert.FromBase64String(payload.Substring(split+1));using(var input=new MemoryStream(packed))using(var zip=new GZipStream(input,CompressionMode.Decompress))using(var output=new MemoryStream()){byte[] buffer=new byte[8192];int count;while((count=zip.Read(buffer,0,buffer.Length))>0){if(output.Length+count>Max)throw new Exception("Embedded estimate exceeds size limit.");output.Write(buffer,0,count);}var plain=output.ToArray();using(var sha=SHA256.Create())if(Convert.ToBase64String(sha.ComputeHash(plain))!=payload.Substring(0,split))throw new Exception("Embedded estimate checksum mismatch.");return new UTF8Encoding(false,true).GetString(plain);}}
}
}
